CREATE TABLE ai_jobs (id CHAR(36) NOT NULL, user_id BIGINT NOT NULL, workflow VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, result MEDIUMTEXT NULL, error_message VARCHAR(500) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), completed_at DATETIME(6) NULL, PRIMARY KEY (id), CONSTRAINT fk_ai_jobs_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX idx_ai_jobs_user_created (user_id, created_at));
